const trigger = $('Execute Workflow Trigger').first().json || {};
const response = $input.first().json.message?.content || $input.first().json.content || '';
const jsonMatch = response.match(/```json\s*\n([\s\S]*?)```/);
const parsed = jsonMatch ? JSON.parse(jsonMatch[1].trim()) : JSON.parse(response);
const classification = {
  intent: parsed.intent || 'inne',
  sender_role: parsed.sender_role || 'unknown',
  detected_tone: parsed.detected_tone || 'semi_formal',
  conversation_stage: parsed.conversation_stage || 'initial',
  urgency: parsed.urgency || 'medium',
  label_id: parsed.label_id || 'Label_2258360176253958758',
  confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.8
};
return { json: { ...trigger, classification } };
